def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Find contiguous bands of rows containing non-background cells.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r + 1 < h and any(v != bg for v in grid[r + 1]):
            r += 1
        bands.append((start, r + 1))
        r += 1

    best = None
    for i, (a0, a1) in enumerate(bands):
        for b0, b1 in bands[i + 1:]:
            if a1 - a0 != b1 - b0:
                continue

            ma = {(y - a0, x) for y in range(a0, a1)
                  for x in range(w) if grid[y][x] != bg}
            mb = {(y - b0, x) for y in range(b0, b1)
                  for x in range(w) if grid[y][x] != bg}

            # The less-complete copy is the target.
            if len(ma) <= len(mb):
                target_start, target, source = a0, ma, mb
            else:
                target_start, target, source = b0, mb, ma

            overlap = len(target & source)
            additions = []
            for dy in range(a1 - a0):
                target_cols = [x for yy, x in target if yy == dy]
                if not target_cols:
                    continue
                right_edge = max(target_cols)
                for yy, x in source:
                    if yy == dy and x > right_edge and (yy, x) not in target:
                        additions.append((target_start + dy, x))

            score = (overlap, len(additions))
            if additions and (best is None or score > best[0]):
                best = (score, additions)

    out = [row[:] for row in grid]
    if best is not None:
        for r, c in best[1]:
            if out[r][c] == bg:
                out[r][c] = 1
    return out
